  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function fail(message: string): never {
  throw new Error(message);
}

/** Validate the JSON input and return a normalized list of tasks. */
export function parseTasks(input: unknown): Task[] {
  if (!isObject(input) || !Array.isArray(input.tasks)) {
    fail("Invalid schema: expected an object with a tasks array.");
  }

