      fail(`Invalid schema: ${label}.duration must be a finite non-negative number.`);
    }

    const dependsValue = rawTask.dependsOn === undefined ? [] : rawTask.dependsOn;
    if (!Array.isArray(dependsValue) || !dependsValue.every((dependency) => typeof dependency === "string")) {
