      if (!ids.has(dependency)) {
        fail(`Invalid schema: task ${JSON.stringify(task.id)} depends on unknown task ${JSON.stringify(dependency)}.`);
      }
    }
  }
  return tasks;
}

function compareSequence(left: string[], right: string[]): number {
